diff --git a/src/utils/format.ts b/src/utils/format.ts
index kkk..lll 100644
--- a/src/utils/format.ts
+++ b/src/utils/format.ts
@@ -1,5 +1,45 @@
-export function formatDate(d: Date): string {
-  return d.toISOString().slice(0, 10);
+type FormatterStrategy = (d: Date) => string;
+
+interface FormatterOptions {
+  strategy?: FormatterStrategy;
+  locale?: string;
+  timezone?: string;
+  fallback?: string;
+}
+
+class DateFormatterFactory {
+  private static instance: DateFormatterFactory;
+  private strategies = new Map<string, FormatterStrategy>();
+
+  private constructor() {
+    this.strategies.set("iso", (d) => d.toISOString().slice(0, 10));
+    this.strategies.set("locale", (d) => d.toLocaleDateString());
+  }
+
+  static getInstance(): DateFormatterFactory {
+    if (!DateFormatterFactory.instance) {
+      DateFormatterFactory.instance = new DateFormatterFactory();
+    }
+    return DateFormatterFactory.instance;
+  }
+
+  register(name: string, strategy: FormatterStrategy): void {
+    this.strategies.set(name, strategy);
+  }
+
+  format(d: Date, opts: FormatterOptions = {}): string {
+    const strategyName = opts.strategy ? "custom" : "iso";
+    const fn = opts.strategy ?? this.strategies.get(strategyName);
+    if (!fn) return opts.fallback ?? "";
+    return fn(d);
+  }
+}
+
+export const dateFormatterFactory = DateFormatterFactory.getInstance();
+
+export function formatDate(d: Date, opts?: FormatterOptions): string {
+  return dateFormatterFactory.format(d, opts);
 }
